import Foundation
import Testing
@testable import MarblesCore

/// Cross-client check: jar and stats functions match the web for every golden zone
/// (ios/Fixtures/golden/{jar,stats}.<zone>.json, generated by `npm run golden`).
struct GoldenJarStatsTests {
    static let zones = ["America/Los_Angeles", "Australia/Lord_Howe", "Asia/Kolkata", "UTC"]

    static let goldenDir = URL(fileURLWithPath: #filePath)
        .deletingLastPathComponent()  // MarblesCoreTests
        .deletingLastPathComponent()  // Tests
        .deletingLastPathComponent()  // MarblesCore
        .deletingLastPathComponent()  // Packages
        .deletingLastPathComponent()  // ios
        .appendingPathComponent("Fixtures/golden")

    static func load(_ kind: String, _ zone: String) throws -> Data {
        let url = goldenDir.appendingPathComponent("\(kind).\(zone.replacingOccurrences(of: "/", with: "_")).json")
        return try Data(contentsOf: url)
    }

    struct JarInput: Decodable {
        let date: String?
        let slots: String?
        let sleep: SleepWindow?
        let nowEpochMs: Double?
        let today: String?
    }

    struct SummaryOut: Decodable {
        let g: Double, b: Double, r: Double, sleep: Double, unlogged: Double
    }

    struct JarCase: Decodable {
        let fn: String
        let input: JarInput
        let output: JSONValue
    }

    struct JarFixture: Decodable { let cases: [JarCase] }

    enum JSONValue: Decodable {
        case bool(Bool), string(String), array([Marble]), summary(SummaryOut), other

        init(from decoder: Decoder) throws {
            let c = try decoder.singleValueContainer()
            if let v = try? c.decode(Bool.self) { self = .bool(v) }
            else if let v = try? c.decode(String.self) { self = .string(v) }
            else if let v = try? c.decode([Marble].self) { self = .array(v) }
            else if let v = try? c.decode(SummaryOut.self) { self = .summary(v) }
            else { self = .other }
        }
    }

    @Test(arguments: zones)
    func jarMatchesWeb(zone: String) throws {
        let fixture = try JSONDecoder().decode(JarFixture.self, from: Self.load("jar", zone))
        let ctx = TimeContext.fixed(zone)
        var passed = 0
        var skipped = 0
        for c in fixture.cases {
            let tag = "\(zone) \(c.fn) \(c.input.date ?? "") \(c.input.nowEpochMs ?? 0)"
            switch (c.fn, c.output) {
            case ("computeMarbles", .array(let expected)):
                let marbles = try computeMarbles(
                    date: try #require(c.input.date), slots: c.input.slots,
                    sleep: try #require(c.input.sleep), now: Self.date(c.input), in: ctx)
                #expect(marbles == expected, "\(tag)")
                passed += 1
            case ("summarize", .summary(let e)):
                let marbles = try computeMarbles(
                    date: try #require(c.input.date), slots: c.input.slots,
                    sleep: try #require(c.input.sleep), now: Self.date(c.input), in: ctx)
                #expect(summarize(marbles) == Summary(g: e.g, b: e.b, r: e.r, sleep: e.sleep, unlogged: e.unlogged), "\(tag)")
                passed += 1
            case ("formatSummary", .string(let expected)):
                let marbles = try computeMarbles(
                    date: try #require(c.input.date), slots: c.input.slots,
                    sleep: try #require(c.input.sleep), now: Self.date(c.input), in: ctx)
                #expect(formatSummary(summarize(marbles)) == expected, "\(tag)")
                passed += 1
            case ("hasLoggedSlots", .bool(let expected)):
                #expect(hasLoggedSlots(c.input.slots) == expected, "\(tag)")
                passed += 1
            case ("isEmptyPastDay", .bool(let expected)):
                #expect(isEmptyPastDay(try #require(c.input.date), try #require(c.input.today), c.input.slots) == expected, "\(tag)")
                passed += 1
            case ("CATEGORY_LABEL", _):
                for color in MarbleColor.allCases {
                    #expect(!categoryLabel(color).isEmpty)
                }
                skipped += 1
            case ("MARBLE_COLORS", _):
                skipped += 1
            default:
                skipped += 1
            }
        }
        print("GoldenJarStats jar \(zone): passed=\(passed) skipped=\(skipped)")
        #expect(passed > 0)
    }

    @Test
    func constantTablesMatchWeb() throws {
        struct Table: Decodable {
            let fn: String
            let output: [String: String]
            enum CodingKeys: String, CodingKey { case fn, output }
            init(from decoder: Decoder) throws {
                let c = try decoder.container(keyedBy: CodingKeys.self)
                fn = try c.decode(String.self, forKey: .fn)
                output = (try? c.decode([String: String].self, forKey: .output)) ?? [:]
            }
        }
        struct F: Decodable { let cases: [Table] }
        let fixture = try JSONDecoder().decode(F.self, from: Self.load("jar", "UTC"))
        for t in fixture.cases {
            if t.fn == "CATEGORY_LABEL" {
                for (k, v) in t.output { #expect(categoryLabel(try #require(MarbleColor(rawValue: k))) == v) }
            } else if t.fn == "MARBLE_COLORS" {
                for (k, v) in t.output { #expect(marbleColorHex(try #require(MarbleColor(rawValue: k))) == v) }
            }
        }
    }

    static func date(_ i: JarInput) -> Date {
        Date(timeIntervalSince1970: (i.nowEpochMs ?? 0) / 1000)
    }

    struct StatsInput: Decodable {
        let dates: [String]?
        let days: [String: DayDoc]?
        let settingsSleep: SleepWindow?
        let nowEpochMs: Double?
        let n: Double?
    }

    struct StatsOut: Decodable {
        struct Hours: Decodable { let g, b, r, sleep, unlogged, notYet, na: Double }
        struct Awake: Decodable { let g, b, r, unlogged: Double }
        struct Day: Decodable { let g, b, r, sleep, unlogged, notYet: Double }
        let hours: Hours
        let awakePct: Awake
        let dayPct: Day
    }

    struct StatsCase: Decodable {
        let fn: String
        let input: StatsInput
        let output: JSONOut
    }

    enum JSONOut: Decodable {
        case stats(StatsOut), number(Double), other
        init(from decoder: Decoder) throws {
            let c = try decoder.singleValueContainer()
            if let v = try? c.decode(StatsOut.self) { self = .stats(v) }
            else if let v = try? c.decode(Double.self) { self = .number(v) }
            else { self = .other }
        }
    }

    struct StatsFixture: Decodable { let cases: [StatsCase] }

    @Test(arguments: zones)
    func statsMatchWeb(zone: String) throws {
        let fixture = try JSONDecoder().decode(StatsFixture.self, from: Self.load("stats", zone))
        let ctx = TimeContext.fixed(zone)
        var passed = 0
        var skipped = 0
        for (i, c) in fixture.cases.enumerated() {
            let tag = "\(zone) #\(i) \(c.fn)"
            switch (c.fn, c.output) {
            case ("computeStats", .stats(let e)):
                let now = Date(timeIntervalSince1970: try #require(c.input.nowEpochMs) / 1000)
                let s = try computeStats(
                    dates: try #require(c.input.dates), days: try #require(c.input.days),
                    settingsSleep: try #require(c.input.settingsSleep), now: now, in: ctx)
                let tol = 1e-9
                func eq(_ a: Double, _ b: Double, _ what: String) {
                    #expect(abs(a - b) < tol, "\(tag) \(what): \(a) vs \(b)")
                }
                eq(s.hours.g, e.hours.g, "h.g"); eq(s.hours.b, e.hours.b, "h.b"); eq(s.hours.r, e.hours.r, "h.r")
                eq(s.hours.sleep, e.hours.sleep, "h.sleep"); eq(s.hours.unlogged, e.hours.unlogged, "h.unlogged")
                eq(s.hours.notYet, e.hours.notYet, "h.notYet"); eq(s.hours.na, e.hours.na, "h.na")
                eq(s.awakePct.g, e.awakePct.g, "a.g"); eq(s.awakePct.b, e.awakePct.b, "a.b")
                eq(s.awakePct.r, e.awakePct.r, "a.r"); eq(s.awakePct.unlogged, e.awakePct.unlogged, "a.unlogged")
                eq(s.dayPct.g, e.dayPct.g, "d.g"); eq(s.dayPct.b, e.dayPct.b, "d.b"); eq(s.dayPct.r, e.dayPct.r, "d.r")
                eq(s.dayPct.sleep, e.dayPct.sleep, "d.sleep"); eq(s.dayPct.unlogged, e.dayPct.unlogged, "d.unlogged")
                eq(s.dayPct.notYet, e.dayPct.notYet, "d.notYet")
                passed += 1
            case ("roundPct", .number(let e)):
                eq(roundPct(try #require(c.input.n)), e, tag)
                passed += 1
            default:
                skipped += 1
            }
        }
        print("GoldenJarStats stats \(zone): passed=\(passed) skipped=\(skipped)")
        #expect(passed > 0)
    }

    private func eq(_ a: Double, _ b: Double, _ tag: String) {
        #expect(abs(a - b) < 1e-9, "\(tag): \(a) vs \(b)")
    }
}
